import Foundation

/// Maps an accent colour to one of the precompiled alternate app icons.
/// iOS only switches between icons compiled into the app, so the continuous
/// accent picker is quantised into hue steps generated by
/// scripts/generate-tinted-icons.py. Keep the constants in sync with it.
enum AppIconVariant {
    static let step = 15
    /// Accent hues the original teal icon already matches (inclusive).
    static let primaryRange = 160...200
    static let monoName = "AppIcon-Mono"
    /// Accents below this saturation (greys, black, white) have no hue to match.
    static let minimumSaturation = 0.15

    static var variantHues: [Int] {
        stride(from: 0, to: 360, by: step).filter { !primaryRange.contains($0) }
    }

    static var allNames: [String] { variantHues.map(name(forHue:)) + [monoName] }

    static func name(forHue degrees: Int) -> String {
        String(format: "AppIcon-Hue%03d", degrees)
    }

    /// Alternate icon name for an accent, or `nil` for the primary icon.
    static func iconName(red: Double, green: Double, blue: Double) -> String? {
        let (hue, saturation) = hueAndSaturation(red: red, green: green, blue: blue)
        guard saturation >= minimumSaturation else { return monoName }
        let nearest = Int((hue / Double(step)).rounded()) * step % 360
        return primaryRange.contains(nearest) ? nil : name(forHue: nearest)
    }

    /// Image set holding a loadable copy of an icon. App icon sets can't be read
    /// with UIImage(named:), so every icon also ships as an `AppIconPreview` image.
    static func previewName(for iconName: String?) -> String {
        guard let iconName, iconName.hasPrefix("AppIcon-") else { return "AppIconPreview" }
        return "AppIconPreview" + iconName.dropFirst("AppIcon".count)
    }

    static func hueAndSaturation(red: Double, green: Double, blue: Double) -> (hue: Double, saturation: Double) {
        let maximum = max(red, green, blue)
        let minimum = min(red, green, blue)
        let delta = maximum - minimum
        guard maximum > 0, delta > 0 else { return (0, 0) }
        var hue: Double
        if maximum == red { hue = (green - blue) / delta }
        else if maximum == green { hue = 2 + (blue - red) / delta }
        else { hue = 4 + (red - green) / delta }
        hue *= 60
        if hue < 0 { hue += 360 }
        return (hue, delta / maximum)
    }
}
